-- ═══════════════════════════════════════════════════════════════════════════
-- CassiTrack — dump dati per la simulazione delle tratte
--
-- Contenuto (solo dati, --data-only: lo schema va creato prima, dalle
-- migrazioni Flyway del backend in src/main/resources/db/migration).
--
--   routes           le linee
--   stops            le fermate, con lat/lon
--   buses            i mezzi (trips.bus_id vi fa riferimento)
--   route_stops      LA SEQUENZA FERMATE DI OGNI LINEA  ← indispensabile
--   route_shapes     i vertici della polilinea, il tracciato su strada
--   trips            le corse: id, route_id, bus_id
--   scheduled_stops  gli orari: trip_id, stop_sequence, arrival_seconds
--
-- Le tabelle sono in ordine di dipendenza, così il caricamento non viola
-- le foreign key. Ricaricare con:
--
--   docker exec -i <container-postgres> psql -U <utente> -d <db> < geometry_dump.sql
--
-- ── Come si ricostruisce lo stops[] di una linea ───────────────────────────
--
-- ATTENZIONE: scheduled_stops NON contiene stop_id. Dalla migrazione V27 la
-- tabella porta solo (trip_id, stop_sequence, arrival_seconds): il QUANDO.
-- Il QUALE fermata è salito al livello della linea, in route_stops. Con le
-- sole stops + trips + scheduled_stops la ricostruzione è impossibile — manca
-- il join intermedio. Il percorso completo è:
--
--   scheduled_stops.trip_id  →  trips.route_id
--                            →  route_stops(route_id, stop_sequence)
--                            →  stops.id  →  lat/lon
--
-- Esempio, le fermate di una corsa in ordine con orario e coordinate:
--
--   SELECT ss.stop_sequence, s.id, s.name, s.lat, s.lon, ss.arrival_seconds
--     FROM scheduled_stops ss
--     JOIN trips t        ON t.id = ss.trip_id
--     JOIN route_stops rs ON rs.route_id = t.route_id
--                        AND rs.stop_sequence = ss.stop_sequence
--     JOIN stops s        ON s.id = rs.stop_id
--    WHERE ss.trip_id = 'LINEA_01_A_21600'
--    ORDER BY ss.stop_sequence;
--
-- Per il tracciato fra una fermata e l'altra (non solo la spezzata fra i
-- punti fermata) usare route_shapes(route_id, seq, lat, lon), ordinata per
-- seq. Due avvertenze sui suoi dati:
--   · route_shapes.is_stop è valorizzato solo sulle linee di andata; sulle
--     linee di ritorno "_R" è false ovunque. Non usarlo per trovare le
--     fermate: usare route_stops.
--   · le linee "_R" hanno la geometria salvata NON invertita (stessi seq
--     dell'andata) mentre il loro route_stops è invertito: vanno percorse a
--     seq decrescente.
-- ═══════════════════════════════════════════════════════════════════════════

-- I dump di pg_dump azzerano il search_path. I trigger di versionamento su
-- queste tabelle chiamano bump_data_version(), che referenzia data_version
-- senza qualificarla di schema: con search_path vuoto il caricamento fallisce
-- con 'relation "data_version" does not exist'. Qui il search_path è forzato
-- a public una volta sola, e le righe che lo azzerano sono state rimosse.
SET search_path = public;

